hooks.register("agent_end", async (ctx) => {
  if (!ctx.success) return;
  const proposal = await createProposalFromMessages(ctx.messages);
  if (!proposal) return;
  const reviewed = await reviewTranscriptForProposal(proposal, ctx);
  await store.save(reviewed, status: "pending");
  const scan = scanSkillContent(reviewed.content);
  if (scan.critical) return store.quarantine(reviewed);
  if (cfg.approvalPolicy === "auto") await applyProposalToWorkspace(reviewed);
});

