/**
 * Creates an attachment for invoked skills to preserve their content across compaction.
 * Only includes skills scoped to the given agent.
 */
function createSkillAttachmentIfNeeded(agentId, invokedSkills) {
  const sorted = sortMostRecentFirst(invokedSkills);
  let usedTokens = 0;
  const included = sorted.filter(skill => {
    const tokens = estimateTokens(skill.body);
    if (usedTokens + tokens > POST_COMPACT_SKILLS_TOKEN_BUDGET) return false;
    usedTokens += tokens;
    return true;
  });
  return { type: "invoked_skills", skills: included };
}

export async function onPostSampling(turnCount, invokedSkills) {
  if (turnCount % 5 !== 0) return;
  const patches = await auxSmallModel.complete({
    schema: [{ section, change, reason }],
    skills: invokedSkills.filter(isProjectScoped),
  });
  const accepted = await SkillImprovementSurvey.present(patches);
  await applySkillImprovement(accepted);
}

function getSkillListingAttachments(agentId: string) {
  const sent = sentSkillNames.get(agentId) ?? new Set();
  const delta = allSkills.filter(s => !sent.has(s.name));
  delta.forEach(s => sent.add(s.name));
  sentSkillNames.set(agentId, sent);
  return delta.map(skillToListingAttachment);
}

